import hashlib
def rot13(s):
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            result.append(chr((ord(c) - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= c <= 'Z':
            result.append(chr((ord(c) - ord('A') + 13) % 26 + ord('A')))
        else:
            result.append(c)
    return ''.join(result)

phrase = 'success'
rot13_phrase = rot13(phrase)
token = hashlib.md5(rot13_phrase.encode()).hexdigest()
print(f'rot13({phrase!r}) = {rot13_phrase!r}')
print(f'md5(rot13({phrase!r})) = {token}')
"

