  "summary": "Successfully demonstrated unrestricted file upload vulnerability on DVWA File Upload page (low security). The upload form at /vulnerabilities/upload/ accepts any file type with no validation. A PHP webshell (shell.php) containing phpinfo() was uploaded via multipart POST with the session cookies (PHPSESSID=9kk32r8pdi340ch33to4hbg0s2, security=low). The server responded with '../../hackable/uploads/shell.php succesfully uploaded!' confirming the upload path. The uploaded file was then accessed at /hackable/uploads/shell.php which executed PHP and returned 'UPLOADED_PHP_WORKS' followed by full phpinfo() output, proving arbitrary PHP code execution on the server.",
  "surfaces": [
    {
      "location": "http://127.0.0.1:8080/vulnerabilities/upload/",
      "kind": "upload",
      "params": ["MAX_FILE_SIZE", "uploaded", "Upload"],
      "auth": "session"
    },
    {
      "location": "http://127.0.0.1:8080/hackable/uploads/",
      "kind": "page",
      "params": [],
      "auth": "none"
    }
