import sys
import html
data = sys.stdin.read()
# Extract the PHP code
start = data.find('&lt;?php')
if start == -1:
    start = data.find('<?php')
if start != -1:
    # Find the closing part
    end = data.find('?&gt;', start)
    if end == -1:
        end = data.find('?>', start)
    if end != -1:
        code = data[start:end+4]
        # Decode HTML entities
        code = html.unescape(code)
        print(code)
    else:
        print('No end found')
else:
    print('No PHP found')
" 2>&1

